rows=[[],[25,26,27,28,29],[25,29],[25,29],[5,6,7,8,9,18,19,20,24,25,29],[5,9,10,11,18,20,24,29],[5,11,18,20,24,25,26,27,28,29],[5,11,18,19,20],[5,6,7,8,11],[8,11],[8,9,10,11],[21,22,23,24,25,26],[21,26],[21,26],[21,26],[21,26],[8,9,10,11,12,13,14,15,16,21,22,23,24,26],[8,16],[8],[8,16],[8],[8,9,10,11,16],[11,16,22,23,24,25,26],[11,16,22,26],[11,12,13,14,15,16,22,23,26],[23,26],[23,24,25,26],[],[],[]]
assert len(rows)==30 and all(all(0<=c<30 for c in r) for r in rows)
grid=[[int(c in rows[r]) for c in range(30)] for r in range(30)]
from collections import deque
outside=set(); q=deque()
for r in range(30):
 for c in [0,29]:
  if not grid[r][c] and (r,c) not in outside: outside.add((r,c)); q.append((r,c))
for c in range(30):
 for r in [0,29]:
  if not grid[r][c] and (r,c) not in outside: outside.add((r,c)); q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  rr,cc=r+dr,c+dc
  if 0<=rr<30 and 0<=cc<30 and not grid[rr][cc] and (rr,cc) not in outside:
   outside.add((rr,cc));q.append((rr,cc))
out=[row[:] for row in grid]
for r in range(30):
 for c in range(30):
  if grid[r][c]: continue
  if any(0<=r+dr<30 and 0<=c+dc<30 and grid[r+dr][c+dc] for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0)):
   out[r][c]=2 if (r,c) in outside else 3
print('\n'.join(' '.join(map(str,row)) for row in out))
print('inside halo coords',[(r,c) for r in range(30) for c in range(30) if out[r][c]==3])

# Find components of 1s and enclosed 0 regions under 4-neighbor connectivity.
from collections import deque
seen1=set(); comps=[]
for r in range(30):
 for c in range(30):
  if grid[r][c] and (r,c) not in seen1:
   comp=set([(r,c)]); seen1.add((r,c)); q=deque([(r,c)])
   while q:
    x,y=q.popleft()
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(x+dx,y+dy)
     if 0<=z[0]<30 and 0<=z[1]<30 and grid[z[0]][z[1]] and z not in seen1:
      seen1.add(z); comp.add(z); q.append(z)
   comps.append(comp)
inside_zero=set((r,c) for r in range(30) for c in range(30) if not grid[r][c] and (r,c) not in outside)
# label enclosed zero components and touching 1-component indices
seen0=set(); regions=[]
for p in inside_zero:
 if p in seen0: continue
 reg={p};seen0.add(p);q=deque([p])
 while q:
  r,c=q.popleft()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   z=(r+dr,c+dc)
   if z in inside_zero and z not in seen0: seen0.add(z);reg.add(z);q.append(z)
 touch=[i for i,comp in enumerate(comps) if any((r+dr,c+dc) in comp for r,c in reg for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))]
 regions.append((reg,touch))
print('1 comps',len(comps),[(i,(min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co)),len(co)) for i,co in enumerate(comps)])
print('inside regions',[(len(reg),(min(r for r,c in reg),max(r for r,c in reg),min(c for r,c in reg),max(c for r,c in reg)),touch) for reg,touch in regions])

closed_comps=set(i for reg,touch in regions for i in touch)
out2=[row[:] for row in grid]
for i in closed_comps:
 for r,c in comps[i]:
  for dr in (-1,0,1):
   for dc in (-1,0,1):
    rr,cc=r+dr,c+dc
    if (dr or dc) and 0<=rr<30 and 0<=cc<30 and not grid[rr][cc]:
     out2[rr][cc]=3 if (rr,cc) not in outside else 2
print(closed_comps)
print('\n'.join(' '.join(map(str,row)) for row in out2))
